// src/plugin/provider/prompt-cache-key.ts
import { Effect } from "effect";
import { define } from "@opencode/plugin/effect/plugin";
var providerIDs = [
  "abliteration-ai",
  "aihubmix",
  "anyapi",
  "auriko",
  "edenai",
  "jalapeno",
  "llama",
  "morph",
  "snowflake-cortex",
  "tencent-tokenhub",
  "upstage",
  "venice"
];
var PromptCacheKeyPlugin2 = define({
  id: "opencode.provider.prompt-cache-key",
  effect: Effect.fn(function* (ctx) {
    yield* ctx.provider.transform((providers) => {
      for (const id of providerIDs) {
        if (!providers.get(id))
          continue;
        providers.update(id, (provider) => {
          provider.compatibility = { ...provider.compatibility, supportsPromptCacheKey: true };
        });
      }
    });
  })
});

export { PromptCacheKeyPlugin2 };
